import React from 'react'
import { View, Text } from 'react-native'

import { styles } from './styles'

export function Cards({ listItemProps, position }: any) {
    //const cardNumber = (`0000${listItemProps.data.lineCards + position}`).slice(-4)
    const cardNumber = String(listItemProps.data.lineCards + position)

    return (
        <View>
            <Text style={[styles.listText, listItemProps.db?.[cardNumber]
                ? { backgroundColor: '#26A744' }
                : { backgroundColor: '#fff', color: '#121212' }
            ]}>
                {(`0000${cardNumber}`).slice(-4)}
            </Text>
        </View>
    )
}
